require_once 'config/auth.php'; require_once 'config/db.php';$name=trim($_GET['name']??'');$st=$pdo->prepare("SELECT p.* FROM Pots p WHERE p.status='published' AND p.pot_maker=? ORDER BY p.name");$st->execute([$name]);$Pots=$st->fetchAll();if(!$Pots){http_response_code(404);exit('Artisan profile not found.');}$title=$name.' · Artisan Profile';include 'partials/header.php';?>
<section class="artisan-hero card"><div class="artisan-avatar large">👤</div><div><span class="eyebrow">DOCUMENTED POT MAKER</span><h1><?=e($name)?></h1><p>Linked to <?=count($Pots)?> published pottery record<?=count($Pots)!==1?'s':''?> in Bayangan Archive.</p></div></section>
<?php $artisanPhones=[]; foreach($Pots as $phonePot){$rawPhone=trim((string)($phonePot['contact_info']??'')); if($rawPhone!=='' && preg_match('/^[+0-9() .-]{7,}$/',$rawPhone)){ $telPhone=preg_replace('/[^0-9+]/','',$rawPhone); $artisanPhones[$telPhone]=$rawPhone; }} ?><section class="card artisan-contact-panel"><div><span class="eyebrow">CONTACT INFORMATION</span><h2>Contact this Pot Maker</h2><p>For questions about pottery, materials, or where to find the products, use the published phone number below.</p><?php if($artisanPhones): foreach($artisanPhones as $telPhone=>$rawPhone): ?><p class="artisan-phone-line"><strong>☎ <?=e($rawPhone)?></strong></p><a class="btn small" href="tel:<?=e($telPhone)?>">Call <?=e($name)?></a><?php endforeach; else: ?><p class="muted">No phone number has been published for this pot maker yet. Please contact the archive administrator for assistance.</p><?php endif; ?></div><div class="actions"><a class="btn small secondary" href="archive.php?maker=<?=urlencode($name)?>">View Pottery in Archive</a></div></section><section class="card"><h2>🏺 Pottery Records</h2><div class="grid2"><?php foreach($Pots as $p):?><a class="card mini-card artisan-pot-card" href="pot.php?id=<?=$p['id']?>"><div class="artisan-pot-thumb"><?php if($p['image_path']):?><img src="<?=e(media_url($p['image_path']))?>" alt="<?=e($p['name'])?>" loading="lazy"><?php else: ?><span>🏺</span><?php endif;?></div><h3><?=e($p['name'])?></h3><p><?=e(mb_strimwidth($p['description'],0,140,'…'))?></p><?php $potPhone=trim((string)($p['contact_info']??'')); $potDigits=preg_replace('/[^0-9+]/','',$potPhone); if($potPhone!=='' && preg_match('/^[+0-9() .-]{7,}$/',$potPhone)): ?><p class="artisan-phone-line"><b>Contact Number:</b> <?=e($potPhone)?></p><span class="btn small" onclick="event.preventDefault();window.location.href='tel:<?=e($potDigits)?>'">☎ Call Seller</span><?php endif; ?></a><?php endforeach;?></div></section><?php include 'partials/footer.php';?>